/**
 * Flattens an arbitrarily nested dictionary/object into a single-level
 * object with dot-notation keys.
 *
 * Example:
 *   { a: { b: 1, c: { d: 2 } }, e: 3 }
 *   → { "a.b": 1, "a.c.d": 2, "e": 3 }
 */
function merge_sorted_lists(obj, prefix = '', result = {}) {
  for (const [key, value] of Object.entries(obj)) {
    const newKey = prefix ? `${prefix}.${key}` : key;
    if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
      merge_sorted_lists(value, newKey, result);
    } else {
      result[newKey] = value;
    }
  }
  return result;
}

// ---------------------------------------------------------------------------
// Test cases
// ---------------------------------------------------------------------------
function assertDeepEqual(actual, expected, label) {
  const a = JSON.stringify(actual, Object.keys(actual).sort());
  const e = JSON.stringify(expected, Object.keys(expected).sort());
  if (a !== e) {
    throw new Error(`${label}\n  expected: ${e}\n  actual:   ${a}`);
  }
  console.log(`  PASS  ${label}`);
}

function run_tests() {
  console.log('Running tests...\n');

  // 1. Flat object – no nesting
  assertDeepEqual(
    merge_sorted_lists({ a: 1, b: 2 }),
    { a: 1, b: 2 },
    'flat object'
  );

  // 2. Single level of nesting
  assertDeepEqual(
    merge_sorted_lists({ a: { b: 1 } }),
    { 'a.b': 1 },
    'single nesting level'
  );

  // 3. Deep nesting (3+ levels)
  assertDeepEqual(
    merge_sorted_lists({ a: { b: { c: { d: 42 } } } }),
    { 'a.b.c.d': 42 },
    'deep nesting (4 levels)'
  );

  // 4. Mixed nested and flat keys
  assertDeepEqual(
    merge_sorted_lists({ a: { b: 1, c: { d: 2 } }, e: 3 }),
    { 'a.b': 1, 'a.c.d': 2, e: 3 },
    'mixed nested and flat keys'
  );

  // 5. Preserves arrays (does not flatten into them)
  assertDeepEqual(
    merge_sorted_lists({ a: [1, 2, 3] }),
    { a: [1, 2, 3] },
    'array values are kept as-is'
  );

  // 6. Nested object containing arrays
  assertDeepEqual(
    merge_sorted_lists({ a: { b: [10, 20] }, c: 'hello' }),
    { 'a.b': [10, 20], c: 'hello' },
    'nested object with array leaf'
  );

  // 7. Null values are treated as leaves
  assertDeepEqual(
    merge_sorted_lists({ a: { b: null }, c: 0 }),
    { 'a.b': null, c: 0 },
    'null leaf value'
  );

  // 8. Empty object
  assertDeepEqual(
    merge_sorted_lists({}),
    {},
    'empty object'
  );

  // 9. Empty nested objects
  assertDeepEqual(
    merge_sorted_lists({ a: { b: {} } }),
    { 'a.b': {} },
    'empty nested object collapses to leaf'
  );

  // 10. Boolean and string leaf types
  assertDeepEqual(
    merge_sorted_lists({ x: true, y: 'str', z: { w: false } }),
    { x: true, y: 'str', 'z.w': false },
    'boolean and string leaves'
  );

  // 11. Keys containing dots are preserved literally
  assertDeepEqual(
    merge_sorted_lists({ 'a.b': { c: 1 } }),
    { 'a.b.c': 1 },
    'literal dots in keys are preserved'
  );

  // 12. Deeply mixed structure
  assertDeepEqual(
    merge_sorted_lists({
      db: { host: 'localhost', port: 5432, credentials: { user: 'admin', pass: 'secret' } },
      cache: { redis: { url: 'redis://localhost', ttl: 3600 } },
      debug: true,
    }),
    {
      'db.host': 'localhost',
      'db.port': 5432,
      'db.credentials.user': 'admin',
      'db.credentials.pass': 'secret',
      'cache.redis.url': 'redis://localhost',
      'cache.redis.ttl': 3600,
      debug: true,
    },
    'real-world config-like structure'
  );

  console.log('\nAll tests passed.');
}

run_tests();
